#include "fold.hpp"

#include <cstdio>
#include <dirent.h>
#include <fstream>
#include <map>
#include <string>
#include <unistd.h>

static bool read_urn(const std::string &path, std::string &day, int &number) {
    std::ifstream in(path);
    std::string banner, key, id, dkey, nkey;
    long long value;
    if (!(in >> banner >> key >> id >> dkey >> day >> nkey >> value) ||
        banner != "URN1" || key != "id" || dkey != "day" || nkey != "n" ||
        id.empty() || day.empty() || value < 0 || value > 2147483647LL) {
        return false;
    }
    number = static_cast<int>(value);
    return true;
}

int n_fold(void) {
    std::map<std::string, long long> days;
    DIR *dir = opendir("/app/snapvat/live");
    if (!dir) return 1;
    bool ok = true;
    while (dirent *ent = readdir(dir)) {
        std::string name = ent->d_name;
        if (name.size() < 5 || name.substr(name.size() - 4) != ".urn") continue;
        std::string day;
        int number = 0;
        if (!read_urn(std::string("/app/snapvat/live/") + name, day, number)) {
            ok = false;
            break;
        }
        days[day] += number;
    }
    closedir(dir);
    if (!ok) return 1;

    int tick = 0;
    { std::ifstream in("/app/snapvat/tick"); in >> tick; }
    ++tick;
    const std::string suffix = "." + std::to_string(getpid());
    const std::string days_tmp = "/app/snapvat/days.tmp" + suffix;
    const std::string emit_tmp = "/app/inkpit/emit.inc" + suffix;
    {
        std::ofstream out(days_tmp, std::ios::trunc);
        if (!out) return 1;
        for (const auto &kv : days) out << kv.first << " " << kv.second << "\n";
        if (!out) { std::remove(days_tmp.c_str()); return 1; }
    }
    {
        std::ofstream out(emit_tmp, std::ios::trunc);
        if (!out) { std::remove(days_tmp.c_str()); return 1; }
        for (const auto &kv : days)
            out << kv.first << " " << kv.second << " tick=" << tick << "\n";
        if (!out) {
            std::remove(days_tmp.c_str()); std::remove(emit_tmp.c_str()); return 1;
        }
    }
    if (std::rename(days_tmp.c_str(), "/app/snapvat/days.tmp") != 0 ||
        std::rename(emit_tmp.c_str(), "/app/inkpit/emit.inc") != 0) {
        std::remove(days_tmp.c_str()); std::remove(emit_tmp.c_str()); return 1;
    }
    { std::ofstream out("/app/snapvat/tick", std::ios::trunc); out << tick << "\n"; }
    return 0;
