#include "admit.hpp"
#include "hull.hpp"

#include <cstdio>
#include <fcntl.h>
#include <fstream>
#include <iostream>
#include <map>
#include <sstream>
#include <string>
#include <sys/file.h>
#include <sys/stat.h>
#include <unistd.h>
#include <vector>

class MillLock {
    int fd_ = -1;
public:
    MillLock() {
        fd_ = open("/app/snapvat/busy.latch", O_RDWR | O_CREAT, 0664);
        if (fd_ >= 0 && flock(fd_, LOCK_EX) != 0) { close(fd_); fd_ = -1; }
    }
    ~MillLock() { if (fd_ >= 0) { flock(fd_, LOCK_UN); close(fd_); } }
    bool good() const { return fd_ >= 0; }
};

static bool valid_id(const std::string &id) {
    if (id.empty()) return false;
    for (unsigned char c : id)
        if (!(c >= 'a' && c <= 'z') && !(c >= 'A' && c <= 'Z') &&
            !(c >= '0' && c <= '9') && c != '_' && c != '-') return false;
    return true;
}

static std::string urn_id(const std::string &path) {
    std::ifstream in(path);
    std::string banner, key, id;
    if (!(in >> banner >> key >> id) || banner != "URN1" || key != "id" || !valid_id(id))
        return "";
    return id;
}

static int copy_atomic(const std::string &src, const std::string &dst) {
    std::ifstream in(src, std::ios::binary);
    if (!in) return 1;
    const std::string tmp = dst + ".tmp." + std::to_string(getpid());
    {
        std::ofstream out(tmp, std::ios::binary | std::ios::trunc);
        if (!out) return 1;
        out << in.rdbuf();
        if (!in.eof() || !out) { std::remove(tmp.c_str()); return 1; }
    }
    if (std::rename(tmp.c_str(), dst.c_str()) != 0) { std::remove(tmp.c_str()); return 1; }
    return 0;
}

static int do_pour(const char *src) {
    mkdir("/app/snapvat", 0755);
    mkdir("/app/snapvat/live", 0755);
    MillLock lock;
    if (!lock.good()) return 1;
    std::string id = urn_id(src);
    if (id.empty()) return 1;
    if (copy_atomic(src, "/app/snapvat/live/" + id + ".urn") != 0) return 1;
    std::ofstream queue("/app/snapvat/poured.txt", std::ios::app);
    if (!queue || !(queue << id << "\n")) return 1;
    return 0;
}

static int write_json() {
    std::map<std::string, long long> days;
    std::ifstream din("/app/snapvat/days.tmp");
    std::string day;
    long long n;
    while (din >> day >> n) days[day] += n;
    if (!din.eof()) return 1;
    std::string cover;
    { std::ifstream in("/app/snapvat/cover.tmp"); if (!(in >> cover)) return 1; }
    std::ostringstream body;
    body << "{\"days\":{";
    bool first = true;
    for (const auto &kv : days) {
        if (!first) body << ',';
        first = false;
        body << '\"' << kv.first << "\":" << kv.second;
    }
    body << "},\"covers\":\"" << cover << "\"}\n";
    const std::string tmp = "/app/inkpit/counts.json.tmp." + std::to_string(getpid());
    { std::ofstream out(tmp, std::ios::trunc); if (!out || !(out << body.str())) return 1; }
    if (std::rename(tmp.c_str(), "/app/inkpit/counts.json") != 0) {
        std::remove(tmp.c_str()); return 1;
    }
    return 0;
}

static int do_steep() {
    MillLock lock;
    if (!lock.good() || op_a() != 0) return 1;
    std::ifstream qin("/app/snapvat/poured.txt");
    std::vector<std::string> queue;
    std::string id;
    while (qin >> id) queue.push_back(id);
    if (queue.empty()) return 1;
    { std::ofstream out("/app/snapvat/last.id", std::ios::trunc); if (!out || !(out << queue.front() << "\n")) return 1; }
    if (run_k() != 0 || write_json() != 0) return 1;
    const std::string qtmp = "/app/snapvat/poured.txt.tmp." + std::to_string(getpid());
    {
        std::ofstream out(qtmp, std::ios::trunc);
        if (!out) return 1;
        for (size_t i = 1; i < queue.size(); ++i) out << queue[i] << "\n";
        if (!out) { std::remove(qtmp.c_str()); return 1; }
    }
    if (std::rename(qtmp.c_str(), "/app/snapvat/poured.txt") != 0) {
        std::remove(qtmp.c_str()); return 1;
    }
    return 0;
}

static int do_board() {
    std::ifstream in("/app/inkpit/counts.json");
    if (!in) return 1;
    std::cout << in.rdbuf();
    return in.bad() ? 1 : 0;
}

int main(int argc, char **argv) {
    if (argc < 2) return 2;
    std::string cmd = argv[1];
    if (cmd == "pour") return argc == 3 ? do_pour(argv[2]) : 2;
    if (cmd == "steep") return argc == 2 ? do_steep() : 2;
    if (cmd == "board") return argc == 2 ? do_board() : 2;
    return 2;
}
